export function makeVillageRoomMoveHandlers(): HandlerEntry[] {
  return VILLAGE_MOVES.map((m) => ({
    commandNo: m.commandNo,
    // 私室施錠 — many village edges lead into residents' 私室 (小鈴/阿求/長屋街
    // の各房間…). A sleeping owner's room is locked (COMF400.ERB:586-605); the
    // 潜入 sneak-in branch is deferred (see room-lock.ts).
    execCheck: (ctx) => {
      const gate = mapCanMove(ctx.state, m.toLocation, ctx.state.master);
      if (!gate.can) {
        return {
          ok: false,
          reason: { kind: "precondition", message: gate.message ?? "进不去" },
        };
      }
      const sleeper = lockedRoomOwner(ctx.state, m.toLocation);
      if (sleeper) {
        return { ok: false, reason: { kind: "precondition", message: lockedRoomMessage(sleeper) } };
      }
      return { ok: true };
    },
    handler: (ctx) => {
      const next = cloneGameState(ctx.state);
      setSlotLocation(next.master, m.toLocation);
      advanceTimeTicks(next, 1);
      // Parity QA P-6b: brought-along (CFLAG:同行) companions follow.
      followCompanions(next, 1);
      const activityEvents = pitfallArrivalEvents(next, m.toLocation, ctx.now());
      return {
        state: next,
        events: [
          ...activityEvents,
          {
            kind: "NARRATION" as const,
            timestamp: ctx.now(),
            text: `%CALLNAME:MASTER% 移动到 ${m.toLocation}。`,
          },
        ],
        outcome: "ok" as const,
      };
    },
  }));
}
